struct FormationReservation {WorldPoint point;float radius;bool air;};
std::optional<WorldPoint> formationPoint(World& world,WorldPoint desired,float radius,PathMovement movement,bool pathing,const std::vector<FormationReservation>& reserved,unsigned maxRing) {
    auto number=[](jass::Real value){return std::bit_cast<float>(value.bits());};auto real=[](float value){return jass::Real::fromBits(std::bit_cast<std::uint32_t>(value));};desired=world.clamp(desired);float x=number(desired.x),y=number(desired.y);bool air=movement==PathMovement::Air;
    auto available=[&](int dx,int dy)->std::optional<WorldPoint>{WorldPoint candidate=world.clamp({real(x+float(dx)*32),real(y+float(dy)*32)});float cx=number(candidate.x),cy=number(candidate.y);for(auto& existing:reserved)if(existing.air==air){float distance=std::max(16.f,radius+existing.radius+2.f),ox=cx-number(existing.point.x),oy=cy-number(existing.point.y);if(ox*ox+oy*oy<distance*distance)return {};}if(pathing && !world.pathPointFree(candidate,radius,movement))return {};return candidate;};
    if(auto point=available(0,0))return point;unsigned checked=1;auto tryPoint=[&](int dx,int dy){++checked;return available(dx,dy);};for(int ring=1;ring<=int(maxRing) && checked<512;++ring){for(int dx=-ring;dx<=ring && checked<512;++dx){if(auto point=tryPoint(dx,-ring))return point;if(checked<512)if(auto point=tryPoint(dx,ring))return point;}for(int dy=-ring+1;dy<ring && checked<512;++dy){if(auto point=tryPoint(-ring,dy))return point;if(checked<512)if(auto point=tryPoint(ring,dy))return point;}}return {};
}
