unsigned dispatchPlayerCommand(ScriptSession& session,const PlayerCommand& command,const std::function<bool()>& keepGoing) {
    if(command.player>=16)return 0;switch(command.kind){case PlayerCommandKind::SetAlliance:return session.setAllianceOption(command.player,command.otherPlayer,command.allianceOption,command.enabled)?1u:0u;case PlayerCommandKind::SetAlliedVictory:return session.setAlliedVictory(command.player,command.enabled)?1u:0u;case PlayerCommandKind::TransferResources:return session.transferResources(command.player,command.otherPlayer,command.gold,command.lumber)?1u:0u;case PlayerCommandKind::AllianceSnapshot:return session.setAllianceSnapshot(command.player,command.otherPlayer,command.allianceOption,command.enabled)?1u:0u;case PlayerCommandKind::Chat:if(command.text.empty() || command.text.size()>1024)return 0;session.chat(command.player,command.text);return 1;case PlayerCommandKind::DialogClick:return session.clickDialog(command.player,command.target)?1u:0u;case PlayerCommandKind::EndCinematic:return session.endCinematic(command.player)?1u:0u;default:break;}bool hasPoint=command.kind==PlayerCommandKind::GroundMove || command.kind==PlayerCommandKind::GroundAttack || command.kind==PlayerCommandKind::GroundPatrol || command.kind==PlayerCommandKind::SpellPoint || command.kind==PlayerCommandKind::SpellPointOrder || command.kind==PlayerCommandKind::BuildAt || command.kind==PlayerCommandKind::ItemPoint || command.kind==PlayerCommandKind::DropItemAt;bool spell=command.kind==PlayerCommandKind::SpellUnit || command.kind==PlayerCommandKind::SpellPoint || command.kind==PlayerCommandKind::SpellImmediate;bool spellOrder=command.kind==PlayerCommandKind::SpellUnitOrder || command.kind==PlayerCommandKind::SpellPointOrder || command.kind==PlayerCommandKind::SpellImmediateOrder;bool inventory=command.kind==PlayerCommandKind::ItemImmediate || command.kind==PlayerCommandKind::ItemUnit || command.kind==PlayerCommandKind::ItemPoint || command.kind==PlayerCommandKind::DropItem || command.kind==PlayerCommandKind::DropItemAt || command.kind==PlayerCommandKind::GiveItem || command.kind==PlayerCommandKind::SwapItem;bool purchase=command.kind==PlayerCommandKind::PurchaseItem || command.kind==PlayerCommandKind::PurchaseUnit;bool production=command.kind==PlayerCommandKind::Train || command.kind==PlayerCommandKind::Research || command.kind==PlayerCommandKind::Upgrade || command.kind==PlayerCommandKind::CancelUpgrade || command.kind==PlayerCommandKind::CancelBuild || command.kind==PlayerCommandKind::CancelProduction || command.kind==PlayerCommandKind::Revive || command.kind==PlayerCommandKind::ReturnResources || command.kind==PlayerCommandKind::LearnSkill;if(!hasPoint && !spell && !spellOrder && !production && !inventory && !purchase && command.kind!=PlayerCommandKind::Stop && command.kind!=PlayerCommandKind::Hold && command.kind!=PlayerCommandKind::TargetOrder && command.kind!=PlayerCommandKind::UnloadUnit && command.kind!=PlayerCommandKind::AbilityAutocast && command.kind!=PlayerCommandKind::RepairAutocast)return 0;if(hasPoint && (!std::isfinite(std::bit_cast<float>(command.xBits)) || !std::isfinite(std::bit_cast<float>(command.yBits))))return 0;if((command.kind==PlayerCommandKind::TargetOrder && (!command.target || !command.order)) || ((command.kind==PlayerCommandKind::SpellUnit || command.kind==PlayerCommandKind::ItemUnit || command.kind==PlayerCommandKind::GiveItem || command.kind==PlayerCommandKind::UnloadUnit) && !command.target) || (inventory && !command.item) || (purchase && !command.objectType) || (spell && !command.ability) || (spellOrder && !command.order) || (command.kind==PlayerCommandKind::SpellUnitOrder && !command.target) || ((command.kind==PlayerCommandKind::BuildAt || command.kind==PlayerCommandKind::Train || command.kind==PlayerCommandKind::Research || command.kind==PlayerCommandKind::Upgrade || command.kind==PlayerCommandKind::Revive || command.kind==PlayerCommandKind::LearnSkill) && !command.objectType))return 0;WorldPoint point{jass::Real::fromBits(command.xBits),jass::Real::fromBits(command.yBits)};unsigned accepted=0;
    bool groupOrder=command.kind==PlayerCommandKind::GroundMove || command.kind==PlayerCommandKind::GroundAttack || command.kind==PlayerCommandKind::GroundPatrol;std::map<std::uint32_t,WorldPoint> destinations;std::vector<FormationReservation> reserved;unsigned maxRing=0;
    if(groupOrder && command.units.size()>1){std::vector<std::uint32_t> mobile;float largest=0;for(auto id:command.units){auto found=session.units().find(id);if(found==session.units().end())continue;auto& u=*found->second;if(!session.canControlUnit(command.player,u) || u.removing || u.hidden() || u.paused || u.stunned() || u.rooted() || u.stationaryBuilding() || u.construction || u.unsummon || std::bit_cast<float>(u.life.bits())<=0 || std::bit_cast<float>(u.currentMoveSpeed().bits())<=0)continue;mobile.push_back(id);if(std::isfinite(u.collision))largest=std::max(largest,std::clamp(u.collision,0.f,512.f));}std::sort(mobile.begin(),mobile.end());mobile.erase(std::unique(mobile.begin(),mobile.end()),mobile.end());if(mobile.size()>1){size_t columns=1;while(columns*columns<mobile.size())++columns;auto rows=(mobile.size()+columns-1)/columns;auto center=session.world()->clamp(point);float spacing=std::max(48.f,largest*2+16.f),x=std::bit_cast<float>(center.x.bits()),y=std::bit_cast<float>(center.y.bits());maxRing=std::min(32u,std::max(8u,unsigned(std::ceil(spacing/32))*2));reserved.reserve(mobile.size());for(size_t index=0;index<mobile.size();++index){size_t row=index/columns,col=index%columns,remaining=std::min(columns,mobile.size()-row*columns);float dx=(float(col)-(float(remaining)-1)*.5f)*spacing,dy=((float(rows)-1)*.5f-float(row))*spacing;destinations.emplace(mobile[index],WorldPoint{jass::Real::fromBits(std::bit_cast<std::uint32_t>(x+dx)),jass::Real::fromBits(std::bit_cast<std::uint32_t>(y+dy))});}}}
    for(auto id:command.units){if(keepGoing && !keepGoing())break;auto found=session.units().find(id);if(found==session.units().end() || (!purchase && !session.canControlUnit(command.player,*found->second)))continue;auto unit=found->second;if(groupOrder && (unit->removing || unit->hidden() || std::bit_cast<float>(unit->life.bits())<=0))continue;std::optional<WorldPoint> destination;if(auto it=destinations.find(id);it!=destinations.end()){if(!std::isfinite(unit->collision) || unit->collision<0 || unit->collision>512)continue;destination=formationPoint(*session.world(),it->second,unit->collision,pathMovement(unit->movementType),unit->pathing,reserved,maxRing);if(!destination)continue;}bool issued=false;switch(command.kind){case PlayerCommandKind::GroundMove:issued=unit->stationaryBuilding()?session.setRally(id,point):session.moveUnit(id,point,851986,destination);break;case PlayerCommandKind::GroundAttack:issued=session.attackMove(id,point,false,destination);break;case PlayerCommandKind::GroundPatrol:issued=session.attackMove(id,point,true,destination);break;case PlayerCommandKind::Stop:issued=session.stopUnit(id);break;case PlayerCommandKind::Hold:issued=session.stopUnit(id,true);break;case PlayerCommandKind::TargetOrder:issued=session.targetOrder(id,command.target,command.order);break;case PlayerCommandKind::SpellUnit:issued=session.castSpell(id,command.ability,command.target);break;case PlayerCommandKind::SpellUnitOrder:issued=session.castOrder(id,command.order,command.target);break;case PlayerCommandKind::SpellPointOrder:issued=session.castPointOrder(id,command.order,point);break;case PlayerCommandKind::SpellImmediateOrder:issued=session.castImmediateOrder(id,command.order);break;case PlayerCommandKind::SpellPoint:issued=session.castSpellAt(id,command.ability,point);break;case PlayerCommandKind::SpellImmediate:issued=session.castSpell(id,command.ability);break;case PlayerCommandKind::BuildAt:issued=session.build(id,command.objectType,point);break;case PlayerCommandKind::Train:issued=session.train(id,command.objectType);break;case PlayerCommandKind::Research:issued=session.research(id,command.objectType);break;case PlayerCommandKind::Upgrade:issued=session.upgradeBuilding(id,command.objectType);break;case PlayerCommandKind::CancelUpgrade:issued=session.cancelBuildingUpgrade(id);break;case PlayerCommandKind::CancelBuild:issued=session.cancelConstruction(id);break;case PlayerCommandKind::CancelProduction:issued=session.cancelProduction(id,command.queueIndex);break;case PlayerCommandKind::Revive:issued=session.queueRevival(id,command.objectType);break;case PlayerCommandKind::ReturnResources:issued=session.returnResources(id);break;case PlayerCommandKind::LearnSkill:issued=session.canManageUnitInventory(command.player,*unit) && session.learnHeroSkill(id,command.objectType);break;case PlayerCommandKind::ItemImmediate:case PlayerCommandKind::ItemUnit:case PlayerCommandKind::ItemPoint:case PlayerCommandKind::DropItem:case PlayerCommandKind::DropItemAt:case PlayerCommandKind::GiveItem:case PlayerCommandKind::SwapItem:{auto item=session.items().find(command.item);if(!session.canManageUnitInventory(command.player,*unit) || item==session.items().end() || item->second->holder!=id)break;if(command.kind==PlayerCommandKind::DropItem)issued=session.orderItemDrop(command.player,id,command.item,{unit->x,unit->y});else if(command.kind==PlayerCommandKind::DropItemAt)issued=session.orderItemDrop(command.player,id,command.item,point);else if(command.kind==PlayerCommandKind::GiveItem)issued=session.orderItemGive(command.player,id,command.item,command.target);else if(command.kind==PlayerCommandKind::SwapItem)issued=session.orderItemSlot(command.player,id,command.item,command.queueIndex);else if(command.kind==PlayerCommandKind::ItemPoint)issued=session.useItemAt(id,command.item,point);else issued=session.useItem(id,command.item,command.kind==PlayerCommandKind::ItemUnit?command.target:0);break;}case PlayerCommandKind::AbilityAutocast:issued=command.ability && session.abilityAutocast(id,command.ability,command.enabled);break;case PlayerCommandKind::RepairAutocast:issued=session.repairAutocast(id,command.enabled);break;case PlayerCommandKind::UnloadUnit:{auto passenger=session.units().find(command.target);if(passenger!=session.units().end() && passenger->second->transport==id)issued=session.unloadUnit(id,command.target);break;}case PlayerCommandKind::PurchaseItem:case PlayerCommandKind::PurchaseUnit:issued=session.purchase(id,command.player,command.objectType,command.kind==PlayerCommandKind::PurchaseItem);break;case PlayerCommandKind::SetAlliance:case PlayerCommandKind::SetAlliedVictory:case PlayerCommandKind::TransferResources:case PlayerCommandKind::AllianceSnapshot:case PlayerCommandKind::Chat:case PlayerCommandKind::DialogClick:case PlayerCommandKind::EndCinematic:break;}if(issued){if(destination){auto current=session.units().find(id);auto expected=command.kind==PlayerCommandKind::GroundMove?851986u:command.kind==PlayerCommandKind::GroundAttack?851983u:851990u;if(current!=session.units().end() && current->second==unit && !unit->removing && unit->currentOrder==expected){auto actual=unit->route.empty()?(unit->combat.attackMove?*unit->combat.attackMove:*destination):unit->route.back();reserved.push_back({actual,unit->collision,pathMovement(unit->movementType)==PathMovement::Air});}}++accepted;if(command.stopOnSuccess)break;}}return accepted;
}
